/**
 * Cinematic brand imagery (generated by scripts/process-images.cjs from
 * assets-src/cinematic). Each entry works with <Picture photo={...} />:
 * `${src}-640|1280.avif|webp` exist; width/height are the originals.
 */
const base = '/images/scenes';

const scene = (name, width, height, alt, caption) => ({ name, src: `${base}/${name}`, width, height, alt, caption });

export const SCENES = {
  'hub-night': scene('hub-night', 896, 1200, 'EV charging under a lit canopy at a RANGER-style highway hub at dusk', 'Highway charging hub'),
  'charging-hub': scene('charging-hub', 896, 1200, 'A highway charging plaza at night with green-lit chargers and parked EVs', 'Charging plaza'),
  'charging-bay': scene('charging-bay', 896, 1200, 'An electric SUV charging in a green-lit bay overlooking the highway', '60 kW DC fast charging'),
  'highway-journey': scene('highway-journey', 896, 1200, 'An electric car on a winding highway at sunset', 'Built for the long drive'),
  'highway-network': scene('highway-network', 1376, 768, 'A highway interchange at dusk with streams of traffic', 'On India’s highways'),
  'charger-product': scene('charger-product', 896, 1200, 'Close-up of a DC fast charger with a green-lit CCS2 connector', 'Dual CCS2 guns'),
  cafe: scene('cafe', 896, 1200, 'A warm, modern highway café interior at night', 'Café & refreshments'),
  breakfast: scene('breakfast', 896, 1200, 'Coffee, a croissant and a breakfast bowl on a wooden table', 'Breakfast'),
  lounge: scene('lounge', 896, 1200, 'A quiet lounge where a traveller works on a laptop', 'Free Wi-Fi & rest area'),
  parking: scene('parking', 1024, 1024, 'Lit parking bays beside chargers at a highway hub', 'Ample parking'),
  restrooms: scene('restrooms', 896, 1200, 'Clean, softly lit modern restrooms', 'Clean restrooms'),
};

export const getScene = (name) => SCENES[name];
